param([Parameter(Mandatory=$true)][string]$GameRoot,[string]$Output=(Join-Path $PSScriptRoot '../../docs/research/rimworld/evidence/plants-xml.json'))
$ErrorActionPreference='Stop'
$assembly=(Get-FileHash -LiteralPath (Join-Path $GameRoot 'Assembly-CSharp.dll') -Algorithm SHA256).Hash.ToLowerInvariant()
if($assembly -ne 'eff7d97949f919fb2b151ebfb906e9be749b63410b7dbda78eeebb7972b245c3'){throw 'Review changed game version before updating plants evidence.'}
$selections=@(
 @('research','Data/Core/Defs/ResearchProjectDefs/ResearchProjects_1.xml',"/Defs/ResearchProjectDef[defName='TreeSowing']",@('baseCost','techLevel','tags','prerequisites')),
 @('stump','Data/Core/Defs/ThingDefs_Plants/Plants_Special.xml',"/Defs/ThingDef[@Name='StumpBase' or defName='ChoppedStump']",@('category','thingClass','statBases','startingHpRange','plant'))
)
function Relative-XPath($leaf,$root){$parts=[Collections.Generic.List[string]]::new();$cursor=$leaf;while($cursor -ne $root){$tag=$cursor.LocalName;$siblings=@($cursor.ParentNode.ChildNodes|Where-Object{$_.NodeType -eq 'Element' -and $_.LocalName -eq $tag});$segment=$tag;if($siblings.Count -gt 1){$segment+='['+([Array]::IndexOf($siblings,$cursor)+1)+']'};$parts.Insert(0,$segment);$cursor=$cursor.ParentNode};return ($parts -join '/')}
$records=[Collections.Generic.List[object]]::new()
foreach($s in $selections){$file=Join-Path $GameRoot $s[1];[xml]$doc=Get-Content -Raw -LiteralPath $file;$sha=(Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash.ToLowerInvariant();$nodes=$doc.SelectNodes($s[2]);if(!$nodes.Count){throw "No nodes: $($s[2])"}
 foreach($node in $nodes){$def=$node.SelectSingleNode('defName');$name=if($def){$def.InnerText}else{$node.GetAttribute('Name')};$xp='/Defs/'+$node.LocalName+$(if($def){"[defName='$name']"}else{"[@Name='$name']"});$leaves=[Collections.Generic.List[object]]::new();$contexts=[Collections.Generic.List[object]]::new()
  foreach($child in $node.SelectNodes('.//*')){$rel=Relative-XPath $child $node;$first=($rel -split '/')[0] -replace '\[\d+\]$','';if($first -notin $s[3] -or $rel -match '(?i)graphic|sound|effect|thought|description|label|texPath|visualSize|topWind|maxMesh'){continue};if($child.Attributes.Count -gt 0){$attrs=[ordered]@{};foreach($a in $child.Attributes){$attrs[$a.Name]=$a.Value};$contexts.Add([ordered]@{xpath=$xp+'/'+$rel;attributes=$attrs})};if($child.SelectNodes('*').Count -eq 0){$leaves.Add([ordered]@{xpath=$xp+'/'+$rel;value=$child.InnerText})}}
  $records.Add([ordered]@{group=$s[0];id=$node.LocalName+'_'+$name;def_name=$name;parent_name=$node.GetAttribute('ParentName');source=[ordered]@{path=$s[1];xpath=$xp;sha256=$sha};selected_roots=$s[3];absent_roots=@($s[3]|Where-Object{$null -eq $node.SelectSingleNode($_)});fields=@($leaves.ToArray());node_attributes=@($contexts.ToArray())})
 }
}
$prior=Get-Content -Raw -LiteralPath (Join-Path $PSScriptRoot '../../docs/research/rimworld/evidence/biomes-xml.json')|ConvertFrom-Json
$reused=@('ThingDef_PlantBaseNonEdible','ThingDef_PlantBase','ThingDef_TreeBase','ThingDef_DeciduousTreeBase','ThingDef_Plant_TreePoplar','ThingDef_Plant_TreePine','ThingDef_Plant_SaguaroCactus','ThingDef_Plant_TreeOak','BiomeDef_TemperateForest','BiomeDef_BorealForest','BiomeDef_Desert')
$defaultPaths=@('plant/dieIfLeafless','plant/dieIfNoSunlight','plant/harvestAfterGrowth','plant/growMinGlow','plant/growOptimalGlow','plant/minGrowthTemperature','plant/minOptimalGrowthTemperature','plant/maxOptimalGrowthTemperature','plant/harvestYieldAffectedByDifficulty')
$absence=[Collections.Generic.List[object]]::new()
foreach($id in $reused|Where-Object{$_ -like 'ThingDef_*'}){$r=@($prior.records|Where-Object id -eq $id);if($r.Count -ne 1){throw "Missing reused $id"};$file=Join-Path $GameRoot $r[0].source.path;if((Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $r[0].source.sha256){throw "Changed reused XML: $id"};[xml]$doc=Get-Content -Raw -LiteralPath $file;$root=$doc.SelectSingleNode($r[0].source.xpath);foreach($p in $defaultPaths){if($null -ne $root.SelectSingleNode($p)){throw "Unexpected override $id/$p"}};$absence.Add([ordered]@{group='biomes';xml_record=$id;paths=$defaultPaths})}
$result=[ordered]@{evidence_id='RW17-PLANTS-XML';version_text=(Get-Content -Raw -LiteralPath (Join-Path $GameRoot 'Version.txt')).Trim();assembly_sha256=$assembly;kind='Minimal new research/stump declarations and explicit class-default absence checks; tree/biome declarations reused unchanged';limitations=@('No effective enabled-mod/DLC Def database evaluation.','Selected values and absence are verified against original XML; no original game executed.','Stump deterioration engine and item-placement success are not simulated.');reused_biomes_records=$reused;default_absence=@($absence.ToArray());records=@($records.ToArray())}
[IO.File]::WriteAllText([IO.Path]::GetFullPath($Output),(($result|ConvertTo-Json -Depth 20) -replace "`r`n","`n")+"`n",[Text.UTF8Encoding]::new($false));Write-Output "Recorded $($records.Count) new XML nodes and $($absence.Count * $defaultPaths.Count) absence checks."
